package com.eventfinder.dao;
import com.eventfinder.model.Event; import com.eventfinder.dto.EventRequest; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.jdbc.core.RowMapper; import org.springframework.stereotype.Repository; import java.util.*;
@Repository public class EventDao {private final JdbcTemplate db; public EventDao(JdbcTemplate db){this.db=db;} private final RowMapper<Event> mapper=(r,n)->new Event(r.getLong("id"),r.getString("title"),r.getString("description"),r.getLong("category_id"),r.getString("category"),r.getDate("event_date").toLocalDate(),r.getTime("start_time").toLocalTime(),r.getTime("end_time").toLocalTime(),r.getString("venue"),r.getString("location"),r.getString("image_url"),r.getString("organiser_name"),r.getString("organiser_email"),r.getInt("capacity"),r.getInt("registered_count"),r.getLong("created_by")); private static final String SELECT="SELECT e.*,c.name category,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status='CONFIRMED') registered_count FROM events e JOIN categories c ON c.id=e.category_id "; public List<Event> all(String q,Long category,String date){StringBuilder sql=new StringBuilder(SELECT+" WHERE e.event_date >= CURDATE()");List<Object> p=new ArrayList<>();if(q!=null&&!q.isBlank()){sql.append(" AND (e.title LIKE ? OR e.location LIKE ? OR e.description LIKE ?)");String x="%"+q+"%";p.add(x);p.add(x);p.add(x);}if(category!=null){sql.append(" AND e.category_id=?");p.add(category);}if(date!=null&&!date.isBlank()){sql.append(" AND e.event_date=?");p.add(date);}sql.append(" ORDER BY e.event_date,e.start_time");return db.query(sql.toString(),mapper,p.toArray());} public Optional<Event> one(long id){return db.query(SELECT+" WHERE e.id=?",mapper,id).stream().findFirst();} public List<Event> mine(long uid){return db.query(SELECT+" WHERE e.created_by=? ORDER BY e.event_date DESC",mapper,uid);} public long create(EventRequest x,long uid){db.update("INSERT INTO events(title,description,category_id,event_date,start_time,end_time,venue,location,image_url,organiser_name,organiser_email,capacity,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)",x.title(),x.description(),x.categoryId(),x.eventDate(),x.startTime(),x.endTime(),x.venue(),x.location(),x.imageUrl(),x.organiserName(),x.organiserEmail(),x.capacity(),uid);return db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);} public int update(long id,EventRequest x){return db.update("UPDATE events SET title=?,description=?,category_id=?,event_date=?,start_time=?,end_time=?,venue=?,location=?,image_url=?,organiser_name=?,organiser_email=?,capacity=? WHERE id=?",x.title(),x.description(),x.categoryId(),x.eventDate(),x.startTime(),x.endTime(),x.venue(),x.location(),x.imageUrl(),x.organiserName(),x.organiserEmail(),x.capacity(),id);} public int delete(long id){return db.update("DELETE FROM events WHERE id=?",id);} public List<Map<String,Object>> categories(){return db.queryForList("SELECT id,name FROM categories ORDER BY name");} }